package com.tripnest.exception;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.ConstraintViolationException; import org.springframework.dao.*; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { private Map<String,Object> body(String message,Object data){return Map.of("status","error","message",message,"data",data==null?Map.of():data);} @ExceptionHandler(ApiException.class) ResponseEntity<?> api(ApiException e){return ResponseEntity.status(e.status).body(body(e.getMessage(),null));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(body("Please correct the highlighted fields.",fields));} @ExceptionHandler({ConstraintViolationException.class,HttpMessageNotReadableException.class}) ResponseEntity<?> malformed(Exception e){return ResponseEntity.badRequest().body(body("The request is malformed or contains an invalid value.",null));} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> conflict(){return ResponseEntity.status(HttpStatus.CONFLICT).body(body("This action conflicts with existing data.",null));} @ExceptionHandler(DataAccessException.class) ResponseEntity<?> database(){return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(body("The service is temporarily unavailable.",null));} @ExceptionHandler(Exception.class) ResponseEntity<?> other(Exception e,HttpServletRequest request){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body("Something went wrong on our side.",null));} }
